function maximumSum(nums: number[]): number {
    const d: number[] = Array(100).fill(0);
    let ans = -1;
    for (const v of nums) {
        let x = 0;
        for (let y = v; y; y = (y / 10) | 0) {
            x += y % 10;
        }
        if (d[x]) {
            ans = Math.max(ans, d[x] + v);
        }
        d[x] = Math.max(d[x], v);
    }
    return ans;
}

impl Solution {
    pub fn maximum_sum(nums: Vec<i32>) -> i32 {
        let mut d = vec![0; 100];
        let mut ans = -1;

        for &v in nums.iter() {
            let mut x: usize = 0;
            let mut y = v;
            while y > 0 {
                x += (y % 10) as usize;
                y /= 10;
            }
            if d[x] > 0 {
                ans = ans.max(d[x] + v);
            }
            d[x] = d[x].max(v);
        }

        ans
    }
}

//Editorial: https://leetcode.com/problems/max-sum-of-a-pair-with-equal-sum-of-digits/discuss/2292858/FIRST-TWO-OF-SAME-KEY-oror-Intuition
class Solution {
public:
    int getsum(int n)
    {
        int sum=0;
        while(n)
        {
            sum+=n%10;
            n/=10;
        }
        return sum;
    }
    int maximumSum(vector<int>& nums) {
        int n=nums.size();
        sort(nums.rbegin(),nums.rend());
        map<int,vector<int>> mp;
        for(auto it:nums)
            mp[getsum(it)].push_back(it);
        int ans=0;
        for(auto &[it,arr]:mp)
        {
            if(arr.size()>=2)
                ans=max(ans,arr[0]+arr[1]);
        }
        return ans==0?-1:ans;
    }
};
